UPDATE "projects" SET "name" = :name, "updated_at" = :__policysql_now_rfc3339, "updated_by" = :__policysql_session_subject_id, "updated_ms" = :__policysql_now_epoch_ms WHERE (("id" = :id) AND ("tenant_id" = :__policysql_session_tenant_id)) RETURNING "id" AS "id", "name" AS "name", "updated_at" AS "updated_at", "updated_ms" AS "updated_ms", CASE WHEN ("tenant_id" = :__policysql_session_tenant_id) THEN TRUE ELSE FALSE END AS "__policysql_check"
